#include <algorithm>
#include <cmath>
#include <numeric>
#include <string>
#include <vector>

class FrameHistory
{
public:
    explicit FrameHistory(std::size_t capacity) : m_capacity{ capacity } {}

    void push(double ms)
    {
        m_samples.push_back(ms);
        if (m_samples.size() > m_capacity) m_samples.erase(m_samples.begin());
    }

    double min() const { return m_samples.empty() ? 0 : *std::min_element(m_samples.begin(), m_samples.end()); }
    double max() const { return m_samples.empty() ? 0 : *std::max_element(m_samples.begin(), m_samples.end()); }
    double average() const { return m_samples.empty() ? 0 : std::accumulate(m_samples.begin(), m_samples.end(), 0.0) / static_cast<double>(m_samples.size()); }

    std::string sparkline() const
    {
        static const char* const bars[]{ "▁", "▂", "▃", "▄", "▅", "▆", "▇", "█" };
        const double top{ max() };
        std::string out;
        for (double v : m_samples)
        {
            int level{ top > 0 ? static_cast<int>(std::lround(7.0 * v / top)) : 0 };
            level = std::clamp(level, 0, 7);
            out += bars[level];
        }
        return out;
    }

private:
    std::size_t m_capacity;
    std::vector<double> m_samples;
};

unitTests:
TEST("statistics") { FrameHistory h{ 10 }; for (double v : { 8.0, 8.0, 16.0, 8.0 }) h.push(v); CHECK_NEAR(h.min(), 8, 1e-9); CHECK_NEAR(h.max(), 16, 1e-9); CHECK_NEAR(h.average(), 10, 1e-9); }
TEST("the example sparkline") { FrameHistory h{ 10 }; for (double v : { 8.0, 8.0, 16.0, 8.0 }) h.push(v); CHECK_EQ(h.sparkline(), std::string("▅▅█▅")); }
TEST("old samples drop out") { FrameHistory h{ 3 }; for (double v : { 50.0, 1.0, 2.0, 3.0 }) h.push(v); CHECK_NEAR(h.max(), 3, 1e-9); CHECK_NEAR(h.average(), 2, 1e-9); }
TEST("all zero") { FrameHistory h{ 3 }; h.push(0); h.push(0); CHECK_EQ(h.sparkline(), std::string("▁▁")); }
TEST("empty") { FrameHistory h{ 3 }; CHECK_NEAR(h.average(), 0, 1e-12); CHECK_EQ(h.sparkline(), std::string("")); }
TEST("lowest and highest levels") { FrameHistory h{ 5 }; h.push(0.1); h.push(100); CHECK_EQ(h.sparkline(), std::string("▁█")); }

